//! Typed consumer of the presentation output.
//!
//! The packet is an authored join, generated by
//! the extraction pipeline.  It carries, per spell, the spell rule
//! steps, the spell-presentation family/upload/present descriptor and the exact unresolved
//! frontier.  Nothing here reads a palette byte, invents an impact tick or
//! treats an upload wait as an impact.
//!
//! `validate` is deliberately independent of the generator: it recomputes every
//! coverage count, refuses a "ready" record that still carries a blocker, and
//! refuses a blocked record with no reason.  A caller cannot supply a count, a
//! phase or a completion opinion.

const std = @import("std");
const validation = @import("validation");

pub const schema = "suikoden-effect-composition/1";
pub const version = "combat-effect-composition.1";
pub const task = "combat-effect-composition";

pub const PresentationContract = struct {
    status: []const u8,
    package: []const u8,
    packet_path: []const u8,
    contract_sha256: []const u8,
    packet_schema: []const u8,
    report_path: ?[]const u8 = null,
    report_sha256: ?[]const u8 = null,
    catalogue_sha256: []const u8,
    reviewed_correction_status: []const u8,
    reviewed_correction_commit: []const u8,
    reviewed_correction_code: []const u8,
    required_interface: []const u8,
    owner: []const u8,
    frontier: []const []const u8,
    consumed: []const []const u8,
    not_consumed: []const []const u8,
};

pub const Input = struct {
    id: []const u8,
    path: []const u8,
    sha256: []const u8,
};

pub const Anchor = struct {
    id: []const u8,
    path: []const u8,
    line: u16,
    pattern: []const u8,
    sha256: []const u8,
};

pub const Boundaries = struct {
    clock: []const u8,
    cast_contact: []const u8,
    cast_finish: []const u8,
    attack_contact: []const u8,
    attack_finish: []const u8,
    projectile_contact: []const u8,
    projectile_finish: []const u8,
};

pub const Atlas = struct {
    slot_base: u16,
    slot_count: u16,
    planes_per_tick: u16,
    ticks: u16,
    origin: [2]u16,
    rect_words: [2]u16,
    columns: u16,
    row_pixels: u16,
    plane_ids: []const []const u8,
    lifetime: []const u8,
};

pub const BlockerInfo = struct {
    code: []const u8,
    detail: []const u8,
    provenance: []const u8,
};

pub const Family = struct {
    id: []const u8,
    section: u8,
    texture_mode: []const u8,
    slot_base: u16,
    plane_bank: []const u8,
    piece_count: u16,
    animation_count: u16,
    palette_status: []const u8,
    slot_range_status: []const u8,
    page_status: []const u8,
    lifetime_status: []const u8,
    blockers: []const []const u8,
};

pub const Step = struct {
    order: u8 = 0,
    op: []const u8,
    target: []const u8,
    power: u16 = 0,
    percent: ?u16 = null,
    duration: ?u8 = null,
    clear_status: ?bool = null,
    failure_percent: ?u8 = null,
    channel: ?u8 = null,
};

pub const RuleEffect = struct {
    status: []const u8,
    effect: []const u8,
    targets: []const []const u8,
    one_time: bool,
    steps: []const Step,
    note: ?[]const u8 = null,
};

pub const FrameEntry = struct {
    piece: u16,
    ticks: u16,
};

pub const PieceEntry = struct {
    slot_offset: u8,
    uv: [2]u8,
    size: [2]u8,
    palette_row: u8,
    flip: u8,
    v_wrap: u8,
};

pub const Piece = struct {
    id: u16,
    name: []const u8,
    entries: []const PieceEntry,
};

pub const Timeline = struct {
    contact: []const u8,
    finish: []const u8,
};

pub const Spell = struct {
    id: []const u8,
    native_spell_id: u8,
    name: []const u8,
    family: []const u8,
    section: u8,
    rule_status: []const u8,
    rule_effect: RuleEffect,
    timeline: Timeline,
    presentation_status: []const u8,
    composition: []const u8,
    upload_ticks: u16,
    upload_slots: u16,
    present_animation: ?u16 = null,
    present_frames: []const FrameEntry,
    present_ticks: u16,
    present_pieces: []const Piece,
    palette_status: []const u8,
    page_status: []const u8,
    lifetime_status: []const u8,
    blockers: []const []const u8,
    lead_ticks: u16,
    residency_status: []const u8,
    composition_status: []const u8,
    present_status: []const u8,
    loop_status: []const u8,
    direct_plane: ?u8 = null,
};

pub const Attack = struct {
    id: []const u8,
    kind: []const u8,
    handler: []const u8,
    track: []const u8,
    target_track: []const u8,
    contact: []const u8,
    finish: []const u8,
    rule_effect: RuleEffect,
    status: []const u8,
    note: ?[]const u8 = null,
};

pub const Qualified = struct {
    id: []const u8,
    effect: []const u8,
    spell: ?[]const u8 = null,
    attack: ?[]const u8 = null,
    rule_effect: RuleEffect,
};

pub const Coverage = struct {
    spells: u16,
    rules_supported: u16,
    rules_partial: u16,
    presentation_ready: u16,
    presentation_blocked: u16,
    upload_present: u16,
    rule_only: u16,
    families: u16,
    attacks: u16,
    qualified_families: u16,
};

pub const Packet = struct {
    schema: []const u8,
    version: []const u8,
    task: []const u8,
    presentation: PresentationContract,
    inputs: []const Input,
    anchors: []const Anchor,
    boundaries: Boundaries,
    atlas: Atlas,
    blockers: []const BlockerInfo,
    families: []const Family,
    spells: []const Spell,
    attacks: []const Attack,
    qualified_families: []const Qualified,
    coverage: Coverage,
};

pub fn load(allocator: std.mem.Allocator, bytes: []const u8) !std.json.Parsed(Packet) {
    const parsed = try std.json.parseFromSlice(Packet, allocator, bytes, .{
        .ignore_unknown_fields = true,
        .allocate = .alloc_always,
    });
    errdefer parsed.deinit();
    try validate(&parsed.value);
    return parsed;
}

fn isHex64(value: []const u8) bool {
    return validation.isHex64(value);
}

pub fn findFamily(packet: *const Packet, id: []const u8) ?Family {
    for (packet.families) |family| if (std.mem.eql(u8, family.id, id)) return family;
    return null;
}

pub fn findSpell(packet: *const Packet, id: []const u8) ?Spell {
    for (packet.spells) |spell| if (std.mem.eql(u8, spell.id, id)) return spell;
    return null;
}

pub fn findAttack(packet: *const Packet, id: []const u8) ?Attack {
    for (packet.attacks) |attack| if (std.mem.eql(u8, attack.id, id)) return attack;
    return null;
}

pub fn spellIndex(packet: *const Packet, id: []const u8) ?usize {
    for (packet.spells, 0..) |spell, index| if (std.mem.eql(u8, spell.id, id)) return index;
    return null;
}

pub fn attackIndex(packet: *const Packet, id: []const u8) ?usize {
    for (packet.attacks, 0..) |attack, index| if (std.mem.eql(u8, attack.id, id)) return index;
    return null;
}

fn hasBlocker(blockers: []const []const u8, code: []const u8) bool {
    for (blockers) |entry| if (std.mem.eql(u8, entry, code)) return true;
    return false;
}

pub fn validate(packet: *const Packet) !void {
    if (!std.mem.eql(u8, packet.schema, schema)) return error.InvalidPacket;
    if (!std.mem.eql(u8, packet.version, version)) return error.InvalidPacket;
    if (!std.mem.eql(u8, packet.task, task)) return error.InvalidPacket;

    const presentation = packet.presentation;
    if (!std.mem.eql(u8, presentation.package, "spell_presentation")) return error.InvalidPacket;
    if (!std.mem.eql(u8, presentation.status, "accepted_parent_partial")) return error.InvalidPacket;
    if (!std.mem.eql(u8, presentation.reviewed_correction_status, "unavailable")) return error.InvalidPacket;
    if (!std.mem.eql(u8, presentation.reviewed_correction_code, "presentation_correction_unavailable")) return error.InvalidPacket;
    if (!std.mem.eql(u8, presentation.required_interface, "spell_identity_to_presentation_frames_and_audio")) return error.InvalidPacket;
    if (!isHex64(presentation.contract_sha256) or !isHex64(presentation.catalogue_sha256)) return error.InvalidPacket;
    if (presentation.frontier.len == 0) return error.InvalidPacket;
    for (presentation.frontier) |code| {
        if (code.len == 0) return error.InvalidPacket;
        var known = false;
        for (known_blockers) |candidate| if (std.mem.eql(u8, candidate, code)) {
            known = true;
        };
        if (!known) return error.InvalidPacket;
    }
    for (packet.inputs) |input| {
        if (input.id.len == 0 or input.path.len == 0 or !isHex64(input.sha256)) return error.InvalidPacket;
    }
    for (packet.anchors) |anchor| {
        if (anchor.id.len == 0 or anchor.path.len == 0 or anchor.line == 0 or anchor.pattern.len == 0) return error.InvalidPacket;
        if (!isHex64(anchor.sha256)) return error.InvalidPacket;
    }
    const b = packet.boundaries;
    const expected_boundaries = [_][]const u8{
        b.clock,             b.cast_contact,  b.cast_finish,
        b.attack_contact,    b.attack_finish, b.projectile_contact,
        b.projectile_finish,
    };
    const expected_names = [_][]const u8{
        "effect_ticks",        "cast_impact",     "cast_frames_total",
        "member_impact",       "member_duration", "projectile_impact_tick",
        "projectile_duration",
    };
    for (expected_boundaries, expected_names) |value, name| {
        if (!std.mem.eql(u8, value, name)) return error.InvalidPacket;
    }

    const atlas = packet.atlas;
    if (atlas.slot_base != 30 or atlas.slot_count != 10 or atlas.planes_per_tick != 1 or atlas.ticks != 10) return error.InvalidPacket;
    if (atlas.plane_ids.len != 10) return error.InvalidPacket;
    if (atlas.lifetime.len == 0) return error.InvalidPacket;

    if (packet.blockers.len == 0) return error.InvalidPacket;
    for (packet.blockers) |info| {
        if (!hasBlocker(known_blockers[0..], info.code)) return error.InvalidPacket;
        if (info.detail.len == 0) return error.InvalidPacket;
    }

    if (packet.families.len != 7) return error.InvalidPacket;
    for (packet.families, 0..) |family, index| {
        var id_buf: [16]u8 = undefined;
        const expected = try std.fmt.bufPrint(&id_buf, "family_{d}", .{index + 1});
        if (!std.mem.eql(u8, family.id, expected)) return error.InvalidPacket;
        if (family.section != index + 1) return error.InvalidPacket;
        if (!std.mem.eql(u8, family.texture_mode, "indexed8")) return error.InvalidPacket;
        if (family.piece_count == 0 or family.animation_count == 0) return error.InvalidPacket;
        if (family.blockers.len == 0) return error.InvalidPacket;
        for (family.blockers) |code| {
            if (!hasBlocker(known_blockers[0..], code)) return error.InvalidPacket;
        }
        if (!std.mem.eql(u8, family.palette_status, "resolved") and !std.mem.eql(u8, family.palette_status, "unresolved")) return error.InvalidPacket;
        if (!std.mem.eql(u8, family.page_status, "ready") and !std.mem.eql(u8, family.page_status, "blocked")) return error.InvalidPacket;
        if (!std.mem.eql(u8, family.lifetime_status, "ready") and !std.mem.eql(u8, family.lifetime_status, "blocked")) return error.InvalidPacket;
    }

    if (packet.spells.len != 33) return error.InvalidPacket;
    var ready: u16 = 0;
    var supported: u16 = 0;
    var partial: u16 = 0;
    var upload_present: u16 = 0;
    var rule_only: u16 = 0;
    for (packet.spells, 0..) |spell, index| {
        var id_buf: [16]u8 = undefined;
        const expected = try std.fmt.bufPrint(&id_buf, "spell_{d}", .{index + 1});
        if (!std.mem.eql(u8, spell.id, expected)) return error.InvalidPacket;
        if (spell.native_spell_id != index + 1) return error.InvalidPacket;
        if (findFamily(packet, spell.family) == null) return error.InvalidPacket;
        if (spell.section != findFamily(packet, spell.family).?.section) return error.InvalidPacket;
        if (!std.mem.eql(u8, spell.rule_status, "supported") and !std.mem.eql(u8, spell.rule_status, "partial")) return error.InvalidPacket;
        if (spell.rule_status[0] == 's') {
            supported += 1;
        } else {
            partial += 1;
        }
        if (spell.rule_effect.steps.len == 0 or !spell.rule_effect.one_time) return error.InvalidPacket;
        if (!std.mem.eql(u8, spell.rule_effect.status, spell.rule_status)) return error.InvalidPacket;
        if (!std.mem.eql(u8, spell.timeline.contact, "cast_impact")) return error.InvalidPacket;
        if (!std.mem.eql(u8, spell.timeline.finish, "cast_frames_total")) return error.InvalidPacket;
        if (!std.mem.eql(u8, spell.presentation_status, "ready") and !std.mem.eql(u8, spell.presentation_status, "blocked")) return error.InvalidPacket;
        if (std.mem.eql(u8, spell.presentation_status, "ready")) {
            ready += 1;
            if (spell.blockers.len != 0) return error.ForgedPresentation;
            if (!std.mem.eql(u8, spell.palette_status, "resolved")) return error.ForgedPresentation;
            if (!std.mem.eql(u8, spell.page_status, "ready")) return error.ForgedPresentation;
            if (!std.mem.eql(u8, spell.lifetime_status, "ready")) return error.ForgedPresentation;
            if (spell.present_animation == null or spell.present_ticks == 0) return error.ForgedPresentation;
        } else {
            if (spell.blockers.len == 0) return error.InvalidPacket;
            if (!hasBlocker(spell.blockers, "palette_data_carrier")) return error.InvalidPacket;
            for (spell.blockers) |code| {
                if (!hasBlocker(known_blockers[0..], code)) return error.InvalidPacket;
            }
        }
        if (spell.upload_ticks != 0 and spell.upload_ticks != 10) return error.InvalidPacket;
        if (spell.lead_ticks != spell.upload_ticks + spell.present_ticks) return error.InvalidPacket;
        if (spell.composition_status.len == 0 or spell.present_status.len == 0 or spell.loop_status.len == 0) return error.InvalidPacket;
        if (std.mem.eql(u8, spell.composition_status, "direct_single_plane")) {
            if (spell.direct_plane == null or spell.upload_ticks != 0 or spell.present_animation != null) return error.InvalidPacket;
            if (!std.mem.eql(u8, spell.composition, "cast_rule_only")) return error.InvalidPacket;
        } else if (spell.direct_plane != null) return error.InvalidPacket;
        if (spell.present_animation != null) {
            var ticks: u32 = 0;
            for (spell.present_frames) |frame| {
                if (frame.ticks == 0) return error.InvalidPacket;
                ticks += frame.ticks;
                var found = false;
                for (spell.present_pieces) |piece| if (piece.id == frame.piece) {
                    found = true;
                };
                if (!found) return error.InvalidPacket;
            }
            if (ticks != spell.present_ticks or spell.present_ticks == 0) return error.InvalidPacket;
            for (spell.present_pieces) |piece| {
                if (piece.entries.len == 0 or piece.entries.len > 4) return error.InvalidPacket;
            }
        }
        if (std.mem.eql(u8, spell.composition, "cast_upload_present_blocked")) upload_present += 1;
        if (std.mem.eql(u8, spell.composition, "cast_rule_only")) rule_only += 1;
    }
    if (supported != 32 or partial != 1) return error.InvalidPacket;

    if (packet.attacks.len != 2) return error.InvalidPacket;
    for (packet.attacks) |attack| {
        if (!std.mem.eql(u8, attack.kind, "attack") and !std.mem.eql(u8, attack.kind, "projectile")) return error.InvalidPacket;
        if (attack.rule_effect.steps.len == 0 or !attack.rule_effect.one_time) return error.InvalidPacket;
        if (attack.contact.len == 0 or attack.finish.len == 0) return error.InvalidPacket;
    }

    if (packet.qualified_families.len != 4) return error.InvalidPacket;
    var has_damage = false;
    var has_heal = false;
    var has_attack = false;
    for (packet.qualified_families) |entry| {
        if (std.mem.eql(u8, entry.effect, "damage")) has_damage = true;
        if (std.mem.eql(u8, entry.effect, "heal")) has_heal = true;
        if (std.mem.eql(u8, entry.effect, "physical_damage")) has_attack = true;
        if (entry.rule_effect.steps.len == 0 or !entry.rule_effect.one_time) return error.InvalidPacket;
        if (entry.spell) |id| {
            const spell = findSpell(packet, id) orelse return error.InvalidPacket;
            if (!std.mem.eql(u8, spell.rule_status, "supported")) return error.InvalidPacket;
            var op_found = false;
            for (spell.rule_effect.steps) |step| if (std.mem.eql(u8, step.op, entry.effect)) {
                op_found = true;
            };
            if (!op_found) return error.InvalidPacket;
        } else if (entry.attack) |id| {
            if (findAttack(packet, id) == null) return error.InvalidPacket;
        } else return error.InvalidPacket;
    }
    if (!has_damage or !has_heal or !has_attack) return error.InvalidPacket;

    const coverage = packet.coverage;
    if (coverage.spells != @as(u16, @intCast(packet.spells.len))) return error.InvalidPacket;
    if (coverage.rules_supported != supported or coverage.rules_partial != partial) return error.InvalidPacket;
    if (coverage.presentation_ready != ready) return error.InvalidPacket;
    if (coverage.presentation_blocked != 33 - ready) return error.InvalidPacket;
    if (coverage.upload_present != upload_present or coverage.rule_only != rule_only) return error.InvalidPacket;
    if (coverage.families != 7 or coverage.attacks != 2 or coverage.qualified_families != 4) return error.InvalidPacket;
}

pub const known_blockers = [_][]const u8{
    "palette_data_carrier",
    "palette_slot_range",
    "page_lifetime_unproven",
    "presentation_termination",
    "impact_timing",
    "finish_timing",
    "direct_plane_residency",
    "rule_partial",
};
